"use client";
// @zeus-internal
import { KeyRound, Plus } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { type ApiKey, FLAT_SPARKLINE, INITIAL_KEYS, type KeyEnvironment, randomHex, TODAY } from "./01-manager/data";
import { type CreatedKey, CreateKeyDialog, RevokeKeyDialog } from "./01-manager/dialogs";
import { KeyRow, type RotatePhase } from "./01-manager/key-row";
const REVEAL_HIDDEN = { opacity: 0, filter: "blur(6px)", y: 14 };
const REVEAL_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
function reveal(index: number, reduce: boolean | null) {
    return {
        initial: reduce ? false : REVEAL_HIDDEN,
        animate: REVEAL_SHOWN,
        transition: { duration: 0.5, delay: index * 0.06, ease: ARTEMIS_EASE_OUT },
    } as const;
}
function EmptyState({ onCreate }: {
    onCreate: () => void;
}) {
    const item = (i: number) => ({
        initial: { opacity: 0, filter: "blur(4px)", y: 8 },
        animate: { opacity: 1, filter: "blur(0px)", y: 0 },
        transition: { duration: 0.45, delay: i * 0.08, ease: ARTEMIS_EASE_OUT },
    });
    return (<div className="art:flex art:flex-col art:items-center art:rounded-3xl art:border art:border-border art:border-dashed art:px-6 art:py-16 art:text-center">
      <motion.span className="art:relative art:grid art:size-14 art:place-items-center art:rounded-full art:bg-muted art:text-muted-foreground" {...item(0)}>
        <svg aria-hidden="true" viewBox="0 0 56 56" className="art:absolute art:inset-0 art:size-full art:-rotate-90">
          <title>Key outline</title>
          <motion.circle cx="28" cy="28" r="27" fill="none" strokeWidth="1" strokeDasharray="170 170" className="art:stroke-border" initial={{ strokeDashoffset: 170 }} animate={{ strokeDashoffset: 0 }} transition={{ duration: 0.8, ease: ARTEMIS_EASE_OUT }}/>
        </svg>
