}
export default function ApiKeysManager() {
    const id = useId();
    const reduce = useReducedMotion();
    const [environment, setEnvironment] = useState<KeyEnvironment>("live");
    const [keys, setKeys] = useState(INITIAL_KEYS);
    const [rotating, setRotating] = useState<Record<string, RotatePhase>>({});
    const [revokeTarget, setRevokeTarget] = useState<ApiKey | null>(null);
    const [creating, setCreating] = useState(false);
    const createdIds = useRef(new Set<string>());
    const pendingCreated = useRef<CreatedKey | null>(null);
    const count = (env: KeyEnvironment) => keys[env].filter((k) => k.status !== "revoked").length;
    const rows = keys[environment];
    const update = (env: KeyEnvironment, keyId: string, patch: (key: ApiKey) => ApiKey) => setKeys((prev) => ({ ...prev, [env]: prev[env].map((k) => (k.id === keyId ? patch(k) : k)) }));
    const rotate = (key: ApiKey) => {
        const env = environment;
        setRotating((r) => ({ ...r, [key.id]: "busy" }));
        window.setTimeout(() => {
            const suffix = randomHex(2);
            update(env, key.id, (k) => ({ ...k, prefix: `${k.prefix.slice(0, -4)}${suffix}`, rotatedNote: "just now" }));
            setRotating((r) => ({ ...r, [key.id]: "done" }));
            window.setTimeout(() => setRotating((r) => ({ ...r, [key.id]: "idle" })), 1400);
        }, 1100);
    };
    const revoke = (key: ApiKey) => {
        update(environment, key.id, (k) => ({ ...k, status: "revoked", revokedAt: TODAY }));
        setRevokeTarget(null);
    };
    const addCreated = (createdKey: CreatedKey) => {
        const keyId = `key-${Date.now()}`;
        if (keys[environment].length === 0)
            createdIds.current.add(keyId);
        const next: ApiKey = {
            id: keyId,
            name: createdKey.name,
            prefix: `fn_${environment}_\u2022\u2022\u2022\u2022${createdKey.secret.slice(-4)}`,
            scopes: createdKey.scopes,
            created: TODAY,
            lastUsed: "Never",
            requests: "0",
            sparkline: FLAT_SPARKLINE,
            status: "active",
        };
        setKeys((prev) => ({ ...prev, [environment]: [next, ...prev[environment]] }));
    };
    const tabs = (["live", "test"] as const).map((env) => ({
        value: env,
        id: `${id}-panel-${env}`,
        ariaControls: `${id}-panel`,
        label: (<>
        {env === "live" ? "Live" : "Test"}
        <span aria-live="polite" className="art:font-mono art:text-muted-foreground art:text-xs art:tabular-nums">
          <ArtemisDigitSwap value={count(env)} direction="down"/>
        </span>
      </>),
    }));
    return (<section className="art:w-full art:font-sans art:text-foreground" aria-labelledby={`${id}-title`}>
      <div className="art:mx-auto art:w-full art:max-w-6xl">
        <motion.div className="art:flex art:flex-col art:gap-5 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-end art:@min-[640px]/artemis:justify-between" {...reveal(0, reduce)}>
          <div className="art:max-w-xl">
            <h2 className="art:font-medium art:text-4xl art:tracking-tight" id={`${id}-title`}>
              API keys
            </h2>
            <p className="art:mt-2 art:text-muted-foreground art:text-sm art:@min-[640px]/artemis:text-base">
              Keys authenticate requests to the Workspace API. Scope them tightly and rotate them often.
            </p>
          </div>
          <ArtemisButton size="md" className="art:h-9 art:shrink-0 art:self-start art:@min-[640px]/artemis:self-auto" onClick={() => setCreating(true)}>
            <Plus className="art:size-4"/>
            Create key
          </ArtemisButton>
        </motion.div>
        <motion.div className="art:mt-8" {...reveal(1, reduce)}>
          <div>
            <ArtemisSegmentedTabs items={tabs} value={environment} onValueChange={(value) => setEnvironment(value as KeyEnvironment)} ariaLabel="Key environment" buttonClassName="art:rounded-full art:gap-2"/>
          </div>
        </motion.div>
        <motion.div id={`${id}-panel`} role="tabpanel" aria-labelledby={`${id}-panel-${environment}`} className="art:mt-5" {...reveal(2, reduce)}>
          <AnimatePresence mode="wait">
            <motion.div key={`${environment}-${rows.length === 0 ? "empty" : "table"}`} exit={{ opacity: 0 }} transition={{ duration: 0.15, ease: "easeIn" }}>
              {rows.length === 0 ? (<EmptyState onCreate={() => setCreating(true)}/>) : (<div className="art:overflow-hidden art:rounded-3xl art:border art:border-border">
                  <table className="art:w-full art:table-auto art:text-left art:text-sm">
                    <caption className="art:sr-only">API keys</caption>
                    <thead className="art:border-border art:border-b art:text-muted-foreground art:text-xs">
                      <tr>
                        <th scope="col" className="art:py-3 art:pr-3 art:pl-5 art:font-normal">
                          Name
                        </th>
                        <th scope="col" className="art:px-3 art:py-3 art:font-normal art:hidden art:@min-[1024px]/artemis:table-cell">
                          Scopes
                        </th>
                        <th scope="col" className="art:px-3 art:py-3 art:font-normal art:hidden art:@min-[1280px]/artemis:table-cell">
                          Created
                        </th>
                        <th scope="col" className="art:px-3 art:py-3 art:font-normal art:hidden art:@min-[768px]/artemis:table-cell">
                          Last used
                        </th>
                        <th scope="col" className="art:px-3 art:py-3 art:font-normal art:hidden art:@min-[640px]/artemis:table-cell">
                          Requests · 7d
                        </th>
                        <th scope="col" className="art:px-3 art:py-3 art:font-normal art:hidden art:@min-[640px]/artemis:table-cell">
                          Status
                        </th>
                        <th scope="col" className="art:py-3 art:pr-5 art:pl-3 art:text-right art:font-normal">
                          <span className="art:sr-only">Actions</span>
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {rows.map((key) => (<KeyRow key={key.id} apiKey={key} rotating={rotating[key.id] ?? "idle"} isNew={createdIds.current.has(key.id)} onRotate={() => rotate(key)} onRevoke={() => setRevokeTarget(key)}/>))}
                    </tbody>
                  </table>
                </div>)}
            </motion.div>
          </AnimatePresence>
        </motion.div>
      </div>
      <RevokeKeyDialog target={revokeTarget} onClose={() => setRevokeTarget(null)} onConfirm={revoke}/>
      <CreateKeyDialog open={creating} environment={environment} onClose={(createdKey) => {
            setCreating(false);
            pendingCreated.current = createdKey;
        }} onClosed={() => {
            const createdKey = pendingCreated.current;
            pendingCreated.current = null;
            if (createdKey)
                addCreated(createdKey);
        }}/>
    </section>);
}

