function AutoHeight({ children }: {
    children: ReactNode;
}) {
    const ref = useRef<HTMLDivElement>(null);
    const [height, setHeight] = useState(0);
    useEffect(() => {
        const el = ref.current;
        if (!el)
            return;
        const observer = new ResizeObserver(([entry]) => setHeight(entry.contentRect.height));
        observer.observe(el);
        return () => observer.disconnect();
    }, []);
    return (<motion.div className="art:overflow-hidden" animate={{ height: height > 0 ? height : "auto" }} transition={ARTEMIS_SPRING_PANEL}>
      <div ref={ref}>{children}</div>
    </motion.div>);
}
export function RevokeKeyDialog({ target, onClose, onConfirm, }: {
    target: ApiKey | null;
    onClose: () => void;
    onConfirm: (key: ApiKey) => void;
}) {
    const [typed, setTyped] = useState("");
    const [phase, setPhase] = useState<"idle" | "busy" | "done">("idle");
    const busy = phase !== "idle";
    const matches = target !== null && typed.trim() === target.name;
    const submit = (event: FormEvent) => {
        event.preventDefault();
        if (!target || !matches || busy)
            return;
        setPhase("busy");
        window.setTimeout(() => {
            setPhase("done");
            window.setTimeout(() => {
                onConfirm(target);
                setPhase("idle");
                setTyped("");
            }, 420);
        }, 800);
    };
