            <Ban className="art:size-4"/>
          </span>
          <DialogTitle as="h2" className="art:mt-4 art:font-medium art:text-xl">
            Revoke this key?
          </DialogTitle>
          <Description className="art:mt-1 art:text-muted-foreground art:text-sm">
            Requests using this key will fail immediately. This can&apos;t be undone.
          </Description>
          <div className="art:mt-5 art:rounded-2xl art:border art:border-border art:px-4 art:py-3">
            <p className="art:font-medium art:text-sm">{target.name}</p>
            <p className="art:mt-0.5 art:font-mono art:text-muted-foreground art:text-xs">{target.prefix}</p>
          </div>
          <ArtemisTextField className="art:mt-5" label="Type the key name to confirm" placeholder={target.name} autoComplete="off" spellCheck={false} data-autofocus="true" autoFocus value={typed} disabled={busy} onChange={(event) => setTyped(event.target.value)}/>
